  ('pt-BR', 'mods.kind.cli.hint', $json$"Um programa neste computador que recebe o pedido e responde com texto, como os agentes de código."$json$::jsonb),
  ('en', 'mods.kind.cli.hint', $json$"A program on this computer that receives the request and answers with text, like the coding agents."$json$::jsonb),
  ('es', 'mods.kind.cli.hint', $json$"Un programa en este equipo que recibe la solicitud y responde con texto, como los agentes de código."$json$::jsonb),
  ('zh-CN', 'mods.kind.cli.hint', $json$"本机上的程序，接收请求并以文本作答，类似编程代理。"$json$::jsonb),
  ('hi', 'mods.kind.cli.hint', $json$"इस कंप्यूटर पर एक प्रोग्राम जो अनुरोध लेता है और टेक्स्ट में जवाब देता है, कोडिंग एजेंट की तरह।"$json$::jsonb),
  ('ar', 'mods.kind.cli.hint', $json$"برنامج على هذا الجهاز يستقبل الطلب ويجيب بالنص، مثل وكلاء البرمجة."$json$::jsonb),
  ('fr', 'mods.kind.cli.hint', $json$"Un programme sur cet ordinateur qui reçoit la demande et répond par du texte, comme les agents de code."$json$::jsonb),
  ('ru', 'mods.kind.cli.hint', $json$"Программа на этом компьютере, которая получает запрос и отвечает текстом, как агенты для кода."$json$::jsonb),
  ('ja', 'mods.kind.cli.hint', $json$"リクエストを受け取ってテキストで答える、このコンピューター上のプログラムです。コーディングエージェントと同じです。"$json$::jsonb),
  ('de', 'mods.kind.cli.hint', $json$"Ein Programm auf diesem Computer, das die Anfrage erhält und mit Text antwortet, wie die Coding-Agenten."$json$::jsonb),
  ('pt-BR', 'mods.kind.api.hint', $json$"Um endereço HTTP compatível com a API da OpenAI ou da Anthropic. Responde com texto e nunca edita o projeto."$json$::jsonb),
  ('en', 'mods.kind.api.hint', $json$"An HTTP address compatible with the OpenAI or Anthropic API. It answers with text and never edits the project."$json$::jsonb),
  ('es', 'mods.kind.api.hint', $json$"Una dirección HTTP compatible con la API de OpenAI o de Anthropic. Responde con texto y nunca edita el proyecto."$json$::jsonb),
  ('zh-CN', 'mods.kind.api.hint', $json$"兼容 OpenAI 或 Anthropic API 的 HTTP 地址。它以文本作答，从不编辑项目。"$json$::jsonb),
  ('hi', 'mods.kind.api.hint', $json$"OpenAI या Anthropic API के साथ संगत एक HTTP पता। यह टेक्स्ट में जवाब देता है और प्रोजेक्ट को कभी संपादित नहीं करता।"$json$::jsonb),
  ('ar', 'mods.kind.api.hint', $json$"عنوان HTTP متوافق مع واجهة OpenAI أو Anthropic البرمجية. يجيب بالنص ولا يعدّل المشروع أبدًا."$json$::jsonb),
  ('fr', 'mods.kind.api.hint', $json$"Une adresse HTTP compatible avec l’API d’OpenAI ou d’Anthropic. Elle répond par du texte et ne modifie jamais le projet."$json$::jsonb),
  ('ru', 'mods.kind.api.hint', $json$"HTTP-адрес, совместимый с API OpenAI или Anthropic. Отвечает текстом и никогда не редактирует проект."$json$::jsonb),
  ('ja', 'mods.kind.api.hint', $json$"OpenAI または Anthropic の API と互換性のある HTTP アドレスです。テキストで答え、プロジェクトを編集することはありません。"$json$::jsonb),
