  ('de', 'mods.args', $json$"Kommandozeile"$json$::jsonb),
  ('pt-BR', 'mods.args.hint', $json$"Argumentos separados por espaço (as aspas mantêm junto um argumento com espaços). {model} vira o modelo que o Jev escolheu; {prompt}, sozinho num argumento, vira o pedido — sem ele, o pedido vai pela entrada padrão."$json$::jsonb),
  ('en', 'mods.args.hint', $json$"Arguments separated by spaces (quotes keep one with spaces together). {model} becomes the model Jev picked; {prompt}, alone in an argument, becomes the request — without it, the request goes through standard input."$json$::jsonb),
  ('es', 'mods.args.hint', $json$"Argumentos separados por espacios (las comillas mantienen junto un argumento con espacios). {model} se convierte en el modelo que eligió Jev; {prompt}, solo en un argumento, se convierte en la solicitud — sin él, la solicitud va por la entrada estándar."$json$::jsonb),
  ('zh-CN', 'mods.args.hint', $json$"以空格分隔的参数（引号可让含空格的参数保持完整）。{model} 会替换为 Jev 选择的模型；{prompt} 单独作为一个参数时会替换为请求——没有它时，请求通过标准输入传入。"$json$::jsonb),
  ('hi', 'mods.args.hint', $json$"स्पेस से अलग आर्ग्युमेंट (उद्धरण चिह्न स्पेस वाले आर्ग्युमेंट को एक साथ रखते हैं)। {model} की जगह Jev का चुना मॉडल आता है; {prompt}, अकेले एक आर्ग्युमेंट में, अनुरोध बन जाता है — इसके बिना अनुरोध मानक इनपुट से जाता है।"$json$::jsonb),
  ('ar', 'mods.args.hint', $json$"وسائط مفصولة بمسافات (علامات الاقتباس تُبقي الوسيط الذي فيه مسافات مجتمعًا). يصبح {model} النموذج الذي اختاره Jev؛ ويصبح {prompt}، منفردًا في وسيط، الطلبَ — ومن دونه يُرسل الطلب عبر الإدخال القياسي."$json$::jsonb),
  ('fr', 'mods.args.hint', $json$"Arguments séparés par des espaces (les guillemets gardent ensemble un argument avec des espaces). {model} devient le modèle choisi par Jev ; {prompt}, seul dans un argument, devient la demande — sans lui, la demande passe par l’entrée standard."$json$::jsonb),
  ('ru', 'mods.args.hint', $json$"Аргументы через пробел (кавычки удерживают вместе аргумент с пробелами). {model} заменяется моделью, выбранной Jev; {prompt}, отдельным аргументом, заменяется запросом — без него запрос передаётся через стандартный ввод."$json$::jsonb),
  ('ja', 'mods.args.hint', $json$"スペース区切りの引数です（引用符で囲むとスペースを含む引数を1つにできます）。{model} は Jev が選んだモデルに、単独の引数の {prompt} はリクエストに置き換わります。これがなければ、リクエストは標準入力で渡されます。"$json$::jsonb),
  ('de', 'mods.args.hint', $json$"Durch Leerzeichen getrennte Argumente (Anführungszeichen halten ein Argument mit Leerzeichen zusammen). {model} wird zum Modell, das Jev gewählt hat; {prompt}, allein in einem Argument, wird zur Anfrage — ohne es geht die Anfrage über die Standardeingabe."$json$::jsonb),
  ('pt-BR', 'mods.args.invalid', $json$"A linha de comando tem um argumento vazio, uma quebra de linha ou um argumento longo demais."$json$::jsonb),
  ('en', 'mods.args.invalid', $json$"The command line has an empty argument, a line break or an argument that is too long."$json$::jsonb),
  ('es', 'mods.args.invalid', $json$"La línea de comandos tiene un argumento vacío, un salto de línea o un argumento demasiado largo."$json$::jsonb),
  ('zh-CN', 'mods.args.invalid', $json$"命令行中有空参数、换行或过长的参数。"$json$::jsonb),
  ('hi', 'mods.args.invalid', $json$"कमांड लाइन में कोई खाली आर्ग्युमेंट, लाइन ब्रेक या बहुत लंबा आर्ग्युमेंट है।"$json$::jsonb),
  ('ar', 'mods.args.invalid', $json$"في سطر الأوامر وسيط فارغ أو فاصل أسطر أو وسيط أطول من اللازم."$json$::jsonb),
  ('fr', 'mods.args.invalid', $json$"La ligne de commande contient un argument vide, un saut de ligne ou un argument trop long."$json$::jsonb),
  ('ru', 'mods.args.invalid', $json$"В командной строке есть пустой аргумент, перевод строки или слишком длинный аргумент."$json$::jsonb),
  ('ja', 'mods.args.invalid', $json$"コマンドラインに空の引数、改行、または長すぎる引数があります。"$json$::jsonb),
  ('de', 'mods.args.invalid', $json$"Die Kommandozeile enthält ein leeres Argument, einen Zeilenumbruch oder ein zu langes Argument."$json$::jsonb),
