  ('es', 'mods.args.tooMany', $json$"La línea de comandos admite como máximo 64 argumentos."$json$::jsonb),
  ('zh-CN', 'mods.args.tooMany', $json$"命令行最多接受 64 个参数。"$json$::jsonb),
  ('hi', 'mods.args.tooMany', $json$"कमांड लाइन में अधिकतम 64 आर्ग्युमेंट हो सकते हैं।"$json$::jsonb),
  ('ar', 'mods.args.tooMany', $json$"يقبل سطر الأوامر 64 وسيطًا على الأكثر."$json$::jsonb),
  ('fr', 'mods.args.tooMany', $json$"La ligne de commande accepte au plus 64 arguments."$json$::jsonb),
  ('ru', 'mods.args.tooMany', $json$"Командная строка принимает не более 64 аргументов."$json$::jsonb),
  ('ja', 'mods.args.tooMany', $json$"コマンドラインの引数は最大 64 個です。"$json$::jsonb),
  ('de', 'mods.args.tooMany', $json$"Die Kommandozeile nimmt höchstens 64 Argumente an."$json$::jsonb),
