  ('en', 'mods.args.placeholder', $json$"Only {model} and {prompt} (alone in an argument) can be used in the command line."$json$::jsonb),
  ('es', 'mods.args.placeholder', $json$"Solo {model} y {prompt} (solo en un argumento) se pueden usar en la línea de comandos."$json$::jsonb),
  ('zh-CN', 'mods.args.placeholder', $json$"命令行中只能使用 {model} 和 {prompt}（单独作为一个参数）。"$json$::jsonb),
  ('hi', 'mods.args.placeholder', $json$"कमांड लाइन में केवल {model} और {prompt} (अकेले एक आर्ग्युमेंट में) इस्तेमाल हो सकते हैं।"$json$::jsonb),
  ('ar', 'mods.args.placeholder', $json$"لا يُستخدم في سطر الأوامر إلا {model} و{prompt} (منفردًا في وسيط)."$json$::jsonb),
