  ('ar', 'mods.planArgs', $json$"سطر أوامر التخطيط"$json$::jsonb),
  ('fr', 'mods.planArgs', $json$"Ligne de commande de planification"$json$::jsonb),
  ('ru', 'mods.planArgs', $json$"Командная строка для планирования"$json$::jsonb),
  ('ja', 'mods.planArgs', $json$"計画用のコマンドライン"$json$::jsonb),
  ('de', 'mods.planArgs', $json$"Kommandozeile für die Planung"$json$::jsonb),
  ('pt-BR', 'mods.planArgs.hint', $json$"Opcional: a linha usada no modo Planejamento. Vazia, o mod usa a mesma linha."$json$::jsonb),
  ('en', 'mods.planArgs.hint', $json$"Optional: the line used in Planning mode. Empty, the mod uses the same line."$json$::jsonb),
  ('es', 'mods.planArgs.hint', $json$"Opcional: la línea usada en el modo Planificación. Vacía, el mod usa la misma línea."$json$::jsonb),
  ('zh-CN', 'mods.planArgs.hint', $json$"可选：规划模式下使用的命令行。留空时，模组使用同一行。"$json$::jsonb),
  ('hi', 'mods.planArgs.hint', $json$"वैकल्पिक: योजना मोड में इस्तेमाल होने वाली लाइन। खाली होने पर मॉड वही लाइन इस्तेमाल करता है।"$json$::jsonb),
  ('ar', 'mods.planArgs.hint', $json$"اختياري: السطر المستخدم في وضع التخطيط. إن كان فارغًا تستخدم الإضافة السطر نفسه."$json$::jsonb),
  ('fr', 'mods.planArgs.hint', $json$"Facultatif : la ligne utilisée en mode Planification. Vide, le mod utilise la même ligne."$json$::jsonb),
  ('ru', 'mods.planArgs.hint', $json$"Необязательно: строка для режима «Планирование». Если пусто, мод использует ту же строку."$json$::jsonb),
  ('ja', 'mods.planArgs.hint', $json$"任意：計画モードで使うコマンドライン。空の場合、Mod は同じコマンドラインを使います。"$json$::jsonb),
  ('de', 'mods.planArgs.hint', $json$"Optional: die Zeile für den Modus Planung. Leer nutzt der Mod dieselbe Zeile."$json$::jsonb),
  ('pt-BR', 'mods.planArgs.hint.required', $json$"A linha que não escreve no projeto: usada no modo Planejamento e sempre que a política de uma organização aperta os agentes."$json$::jsonb),
  ('en', 'mods.planArgs.hint.required', $json$"The line that does not write to the project: used in Planning mode and whenever an organization's policy tightens the agents."$json$::jsonb),
  ('es', 'mods.planArgs.hint.required', $json$"La línea que no escribe en el proyecto: se usa en el modo Planificación y siempre que la política de una organización restringe a los agentes."$json$::jsonb),
  ('zh-CN', 'mods.planArgs.hint.required', $json$"不写入项目的命令行：用于规划模式，以及组织策略收紧代理权限的任何时候。"$json$::jsonb),
  ('hi', 'mods.planArgs.hint.required', $json$"वह लाइन जो प्रोजेक्ट में नहीं लिखती: योजना मोड में और जब भी किसी संगठन की नीति एजेंटों को सख़्त करती है, तब इस्तेमाल होती है।"$json$::jsonb),
  ('ar', 'mods.planArgs.hint.required', $json$"السطر الذي لا يكتب في المشروع: يُستخدم في وضع التخطيط وكلما شدّدت سياسة مؤسسة القيود على الوكلاء."$json$::jsonb),
  ('fr', 'mods.planArgs.hint.required', $json$"La ligne qui n’écrit pas dans le projet : utilisée en mode Planification et chaque fois que la politique d’une organisation restreint les agents."$json$::jsonb),
  ('ru', 'mods.planArgs.hint.required', $json$"Строка, которая не пишет в проект: используется в режиме «Планирование» и всякий раз, когда политика организации ужесточает правила для агентов."$json$::jsonb),
  ('ja', 'mods.planArgs.hint.required', $json$"プロジェクトに書き込まないコマンドライン。計画モードと、組織のポリシーがエージェントを制限するときに使われます。"$json$::jsonb),
  ('de', 'mods.planArgs.hint.required', $json$"Die Zeile, die nicht ins Projekt schreibt: genutzt im Modus Planung und immer dann, wenn die Richtlinie einer Organisation die Agenten einschränkt."$json$::jsonb),
  ('pt-BR', 'mods.planArgs.required', $json$"Um mod que escreve no projeto precisa de uma linha de comando de planejamento que não escreva."$json$::jsonb),
  ('en', 'mods.planArgs.required', $json$"A mod that writes to the project needs a planning command line that does not."$json$::jsonb),
  ('es', 'mods.planArgs.required', $json$"Un mod que escribe en el proyecto necesita una línea de comandos de planificación que no escriba."$json$::jsonb),
